define({"topics":[{"title":"Tools overview","shortdesc":"<p class=\"shortdesc\">The patient handling alignment procedure is to be completed using the patient handling and magnet leveling tool kit (<span class=\"ph\">5897979<\/span>) and the <cite class=\"cite\"><span class=\"ph\">MR Patient Handling Alignment Macro Tool<\/span><\/cite> (<span class=\"ph\">DOC2372458<\/span>).<\/p>","href":"c_ToolsOverview.html","attributes":{"data-id":"id_2025545"},"menu":{"hasChildren":false},"tocID":"id_2025545-d46e8399","topics":[]},{"title":"Aligning the bridge and rear pedestal (z-dir and x-dir)","shortdesc":"<p class=\"shortdesc\">Align the front endbell-bridge longitudinal (z-dir) offset and the bridge in the lateral (x-dir) direction (left to right of the magnet bore).<\/p>","href":"t_BridgeAndRearPedestalAlignmentz-dirAndX-dir.html","attributes":{"data-id":"id_2025546"},"menu":{"hasChildren":false},"tocID":"id_2025546-d46e8514","topics":[]},{"title":"Adjusting the dock hook tension","shortdesc":"<p class=\"shortdesc\">Adjust the dock hook tension when the force required to engage the dock pedal is minimal or too much (indicating the hook is either too loose or too tight).<\/p>","href":"t_AdjustingTheDockHookTension_DV.html","attributes":{"data-id":"id_2040682"},"menu":{"hasChildren":false},"tocID":"id_2040682-d46e8619","topics":[]},{"title":"Aligning the patient table angle (rotation about y-axis) and offset (x-dir)","shortdesc":"<p class=\"shortdesc\">Measure the distance between the table top and bridge top, measure the angle and offset of the table with the horizontal rulers, and adjust the table accordingly.<\/p>","href":"t_AligningThePatientTableAngleRotationAboutY-axisAndOffsetx-dir.html","attributes":{"data-id":"id_2025551"},"menu":{"hasChildren":false},"tocID":"id_2025551-d46e8724","topics":[]},{"title":"Measuring the bridge and rear pedestal heights","shortdesc":"<p class=\"shortdesc\">Measure the height of the rear pedestal, bridge, and bridge in the body coil, and record the measurements in the macro tool.<\/p>","href":"t_MeasuringTheBridgeAndRearPedestalHeights.html","attributes":{"data-id":"id_2025642"},"menu":{"hasChildren":false},"tocID":"id_2025642-d46e8829","topics":[]},{"title":"Aligning the bridge and rear pedestal (y-dir)","shortdesc":"<p class=\"shortdesc\">If necessary, adjust the height of the rear pedestal or bridge, and record new height measurements in the macro tool.<\/p>","href":"t_AligningTheBridgeAndRearPedestaly-dir.html","attributes":{"data-id":"id_2025548"},"menu":{"hasChildren":false},"tocID":"id_2025548-d46e8934","topics":[]},{"title":"Measuring the patient table height","shortdesc":"<p class=\"shortdesc\">Measure the height of the dock bosses and patient table, make adjustments to the dock boss height if necessary, and note the measurements for entry in the macro tool.<\/p>","href":"t_MeasuringTheTableHeight.html","attributes":{"data-id":"id_2025643"},"menu":{"hasChildren":false},"tocID":"id_2025643-d46e9039","topics":[]},{"title":"Adjusting the patient table height (y-dir)","shortdesc":"<p class=\"shortdesc\">If necessary, adjust the height of the patient table and table casters, and record new height measurements in the macro tool.<\/p>","href":"t_AdjustingThePatientTableHeighty-dir.html","attributes":{"data-id":"id_2025549"},"menu":{"hasChildren":false},"tocID":"id_2025549-d46e9144","topics":[]},{"title":"Doing the pass\/fail check","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_DoingThePassfailCheck.html","attributes":{"data-id":"id_2025743"},"menu":{"hasChildren":false},"tocID":"id_2025743-d46e9249","topics":[]},{"title":"Uploading data","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_UploadingData.html","attributes":{"data-id":"id_2025745"},"menu":{"hasChildren":false},"tocID":"id_2025745-d46e9353","topics":[]}]});